// ============================================================================
// TORAH VERIFY — relire des traductions DÉJÀ FAITES (azy.daily#669, point 1)
// ============================================================================
//
// POURQUOI CE WEBHOOK EXISTE, ET PAS UNE RELECTURE DANS LE CALLBACK DU LOT
//
// Le chemin lot ne relisait rien : `Torah_Batch_Dispatcher` et
// `Torah_Batch_Callback` portaient ZÉRO occurrence de `verify`. Et le lot part
// dès 10 segments, donc les vraies pages de Talmud n'étaient jamais relues.
//
// ⚠️ La relire DANS le callback était impossible proprement. Le callback est
// déclenché APRÈS la fin du lot — jusqu'à 24 h chez Anthropic — par le
// `Claude - Batch Poller` partagé. La clé du relecteur devrait donc SURVIVRE
// jusque-là, c'est-à-dire être stockée dans le metadata du lot, qui traverse le
// soumetteur, l'API Anthropic et le poller. Ce serait une clé BYOT AU REPOS
// dans une infrastructure partagée.
//
// Or le dispatcher évite précisément ça : `Build Requests` envoie `api_key` au
// soumetteur comme credential d'appel, À CÔTÉ de `metadata`, jamais dedans.
// Parker une clé de relecture dans le metadata serait une régression.
//
// D'où ce webhook : la relecture se demande APRÈS COUP, avec la clé dans le
// corps de la requête, comme partout ailleurs en BYOT. Trois conséquences
// heureuses :
//   · il sert les DEUX chemins, lot comme synchrone ;
//   · il permet de relire à nouveau chez un AUTRE fournisseur sans retraduire ;
//   · aucune clé ne survit à la requête.
//
// L'appelant sait quand appeler : le callback publie déjà
// `translation_complete` sur `llm:results:stream`, avec `job_id` et
// `correlation_id`.
//
// ⚠️ CE NŒUD NE PERSISTE RIEN. Il rend les verdicts à l'appelant. La mise en
// base passe par la colonne `review` (chatbot.api#365) et le nœud
// `Prepare Save` du Router — point 3 de l'issue, séparé.
// ============================================================================
const body = $input.first().json.body || $input.first().json;

const erreurs = [];
const segments = Array.isArray(body.segments) ? body.segments : [];
if (segments.length === 0) erreurs.push('Le champ "segments" est requis (tableau non vide)');

const PROVIDERS = ['anthropic', 'openai', 'google', 'mistral', 'ollama-cloud'];
const provider = String(body.verify_provider || 'anthropic').toLowerCase();
if (PROVIDERS.indexOf(provider) === -1) {
  erreurs.push('Le champ "verify_provider" doit valoir ' + PROVIDERS.join(', ')
    + (provider === 'gemini' ? ' et Gemini se nomme google' : ''));
}

// Même cascade que Torah Translate Simple, au nom de champ près : la clé
// dédiée, puis `api_key` SI et SEULEMENT SI le fournisseur est anthropic (ne
// jamais envoyer la clé d'un fournisseur à un autre), puis le trousseau.
const cle = body.verify_api_key
  || (provider === 'anthropic' ? body.api_key : null)
  || (body.plugin_context && body.plugin_context.api_keys
      && body.plugin_context.api_keys[provider])
  || null;
if (!cle && erreurs.length === 0) {
  erreurs.push('Aucune cle pour le fournisseur ' + provider
    + ' — fournir "verify_api_key" ou "plugin_context.api_keys.' + provider + '"');
}

if (erreurs.length > 0) {
  return [{ json: { valide: false, erreur: {
    code: 400, message: erreurs.join(', '), status: 'BAD_REQUEST' } } }];
}

const modele = body.verify_model || 'claude-sonnet-4-6';
const instruction = [
  'Tu relis une traduction de texte talmudique. Tu ne la remplaces pas.',
  '',
  'Signale en priorite les ecarts de SENS, meme minuscules en nombre de mots',
  "(sens d'un terme, nuance, registre, negation, portee d'une proposition).",
  'Un ecart court peut etre le plus grave. Ne te limite pas aux fautes visibles.',
  '',
  'Reponds UNIQUEMENT par un objet JSON, sans texte autour et sans balises de code :',
  '{ "approved": true|false, "confidence": 0.0-1.0,',
  '  "issues": [{ "severite": "sens"|"style"|"forme", "extrait": "...", "explication": "..." }],',
  '  "suggestion": "ta propre traduction si tu en proposes une, meme si tu approuves",',
  '  "notes": "..." }'
].join('\n');

const langues = { he: 'hebreu', ar: 'arameen', en: 'anglais', fr: 'francais' };
const nomLangue = (c) => langues[String(c || '').toLowerCase()] || String(c || 'inconnue');

// ⚠️ Un segment sans traduction ne se relit pas : on le rend avec son motif
// plutôt que de l'écarter en silence. L'appelant doit retrouver TOUS ses
// segments dans la réponse, sinon il ne sait pas lequel manque.
const prepares = segments.map((seg, rang) => {
  const texte = seg.translation || seg.translated_text || '';
  const source = seg.source_text || seg.text || '';
  const commun = {
    valide: true,
    rang: rang,
    segment_id: seg.segment_id || null,
    commentary_id: seg.commentary_id || null,
    verify_provider: provider,
    verify_model: modele
  };
  if (!texte || !source) {
    return { json: Object.assign({}, commun, {
      relisible: false,
      verify_skipped: !texte ? 'traduction_absente' : 'source_absente'
    }) };
  }
  const corps = [
    'Original (' + nomLangue(seg.source_language || body.source_language || 'he') + ') :',
    source,
    '',
    seg.english_pivot ? 'Pivot anglais :\n' + seg.english_pivot + '\n' : '',
    'Traduction a relire (' + nomLangue(seg.target_language || body.target_language || 'fr') + ') :',
    texte
  ].filter(Boolean).join('\n');
  return { json: Object.assign({}, commun, {
    relisible: true,
    verify_skipped: null,
    _verify: {
      provider: provider,
      model: modele,
      api_key: cle,
      max_tokens: 2000,
      temperature: 0,
      system: instruction,
      messages: [{ role: 'user', content: corps }]
    },
    _demande_a: new Date().toISOString()
  }) };
});

return prepares;

// ============================================================================
// APPLIQUER VERDICT — mêmes règles que Torah Translate Simple
// ============================================================================
// ⚠️ Recollage PAR INDEX. Le nœud HTTP remplace le json de l'item par la
// réponse, donc le `rang` posé en amont est perdu. n8n préserve l'ordre des
// items, et `Vérifier (LLM)` tourne en `neverError` : aucun item ne disparaît.
//
// ⚠️ POURQUOI LES SEGMENTS NON RELISIBLES PASSENT QUAND MÊME PAR LE RELAIS
// Un nœud HTTP ne se saute pas item par item. Deux options existaient :
//   · brancher un IF avant, et faire converger deux branches ici — mais
//     l'ordre des items n'est PAS garanti à travers une convergence, et le
//     recollage par index casserait, en silence, sur le mauvais segment ;
//   · appeler le relais pour tout le monde, avec un corps bidon pour les non
//     relisibles — il répond 400 localement, SANS appel LLM donc sans coût, et
//     ce nœud l'ignore puisqu'il sort avant de lire la réponse (`!d.relisible`).
// La seconde est retenue : un 400 local gratuit vaut mieux qu'un verdict
// attribué au mauvais segment.
// Même technique que `Torah Batch Callback`, qui recolle `/save-batch` par
// index.
const demandes = $('Validate Input').all().map(i => i.json);
const reponses = $input.all().map(i => i.json);

const SEVERITES = ['sens', 'style', 'forme'];

const sortie = demandes.map((d, i) => {
  const base = {
    segment_id: d.segment_id,
    commentary_id: d.commentary_id,
    verification: null,
    verify_skipped: d.verify_skipped || null
  };
  if (!d.relisible) return base;

  const rep = reponses[i] || {};
  const code = rep.statusCode || 200;
  const brut = rep.body !== undefined ? rep.body : rep;
  if (code >= 400) {
    return Object.assign(base, { verify_skipped: 'relecteur_http_' + code });
  }

  // Le texte rendu par llm-call-messages est en `data.text`, et nulle part
  // ailleurs au premier niveau de l'enveloppe (azy.daily#642 — l'ancien code
  // lisait `content || text || message`, trois clés inexistantes, et ne rendait
  // JAMAIS d'avis).
  const texte = brut && ((brut.data && brut.data.text) || brut.content
    || brut.text || brut.message || '');
  if (!texte || typeof texte !== 'string') {
    return Object.assign(base, { verify_skipped: 'relecteur_reponse_vide' });
  }

  let avis = null;
  try {
    let s = texte.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    const d0 = s.indexOf('{'), fin = s.lastIndexOf('}');
    if (d0 >= 0 && fin > d0) s = s.slice(d0, fin + 1);
    avis = JSON.parse(s);
  } catch (e) {
    return Object.assign(base, { verify_skipped: 'relecteur_json_illisible' });
  }
  if (!avis || typeof avis !== 'object') {
    return Object.assign(base, { verify_skipped: 'relecteur_json_illisible' });
  }

  // ⚠️ `approved` DOIT être strictement booléen. `avis.approved !== false`
  // comptait un verdict MUET comme une approbation, et aucun contrôle côté api
  // ne peut le rattraper : un `true` fabriqué ici lui arrive impeccable.
  if (avis.approved !== true && avis.approved !== false) {
    return Object.assign(base, { verify_skipped: 'relecteur_avis_sans_verdict' });
  }

  const c = avis.confidence;
  const confiance = (typeof c === 'number' && isFinite(c) && c >= 0 && c <= 1) ? c : null;

  // Normalisation avant de rendre quoi que ce soit : un 422 d'api ferait perdre
  // la traduction entière, et sur /save-batch LE LOT ENTIER.
  const problemes = [];
  let ecartees = 0;
  for (const pb of (Array.isArray(avis.issues) ? avis.issues : [])) {
    if (!pb || typeof pb !== 'object'
        || typeof pb.extrait !== 'string' || typeof pb.explication !== 'string') {
      ecartees++;
      continue;
    }
    const sev = String(pb.severite || '').toLowerCase();
    problemes.push({
      severite: SEVERITES.indexOf(sev) >= 0 ? sev : 'forme',
      extrait: pb.extrait,
      explication: pb.explication
    });
  }

  return Object.assign(base, {
    verify_skipped: null,
    // Forme STRICTEMENT identique à `review` (chatbot.api#365) : l'API refuse
    // les champs inconnus, donc rien de plus ici. Pas de `divergence` : elle
    // le calcule elle-même.
    verification: {
      reviewer: { provider: d.verify_provider, model: d.verify_model },
      reviewed_at: d._demande_a,
      approved: avis.approved,
      confidence: confiance,
      issues: problemes,
      issues_ecartees: ecartees,
      suggestion: avis.suggestion || null,
      notes: avis.notes || null
    }
  });
});

return sortie.map(json => ({ json }));

// Bilan + verdicts complets. Contrairement au bilan du job (point 8), ICI le
// texte intégral est rendu : c'est une réponse synchrone à un appelant qui l'a
// demandée, pas une charge de job qui transiterait par Redis.
const items = $input.all().map(i => i.json);
const pd = $('Validate Input').first().json;
const body = $('Webhook Trigger').first().json.body || {};

const relus = items.filter(i => i.verification);
const sauts = items.reduce((acc, i) => {
  if (i.verify_skipped) acc[i.verify_skipped] = (acc[i.verify_skipped] || 0) + 1;
  return acc;
}, {});

const reserves = relus.filter(i => i.verification.approved === true
  && ((i.verification.issues || []).length > 0 || i.verification.suggestion != null));

return [{ json: {
  success: true,
  job_id: body.job_id || null,
  correlation_id: body.correlation_id || null,
  reviewer: pd.verify_provider + '/' + pd.verify_model,
  total: items.length,
  relus: relus.length,
  non_relus: items.length - relus.length,
  approuves: relus.filter(i => i.verification.approved === true).length,
  refuses: relus.filter(i => i.verification.approved === false).length,
  // « Approuvé avec réserves » : calculé, jamais stocké comme `!approved`.
  avec_reserves: reserves.length,
  issues_ecartees: relus.reduce((s, i) => s + (i.verification.issues_ecartees || 0), 0),
  sauts: sauts,
  verdicts: items
} }];

const e = $input.first().json.erreur || {
  code: 400, message: 'requete invalide', status: 'BAD_REQUEST' };
return [{ json: { success: false, error: e } }];
